     1→// packages/core/src/account/ops/exchanges/okx.test.ts
     2→
     3→import { describe, it, expect } from "vitest";
     4→import { okxExchange } from "./okx";
     5→
     6→describe("okxExchange", () => {
     7→  describe("meta", () => {
     8→    it("has correct id and fields", () => {
     9→      expect(okxExchange.id).toBe("okx");
    10→      expect(okxExchange.name).toBe("OKX");
    11→      expect(okxExchange.fields).toEqual(["api_key", "secret", "passphrase"]);
    12→    });
    13→
    14→    it("has referral and api doc URLs", () => {
    15→      expect(okxExchange.referral_url).toBeDefined();
    16→      expect(okxExchange.api_doc_url).toBeDefined();
    17→    });
    18→  });
    19→
    20→  describe("sign", () => {
    21→    it("produces correct HMAC-SHA256 Base64 signature", () => {
    22→      const credentials = {
    23→        api_key: "test-key",
    24→        secret: "test-secret",
    25→        passphrase: "test-pass",
    26→      };
    27→      const params = {
    28→        method: "GET" as const,
    29→        path: "/api/v5/account/balance",
    30→        timestamp: "2026-05-14T10:00:00.000Z",
    31→      };
    32→
    33→      const result = okxExchange.sign(credentials, params);
    34→
    35→      expect(result.url).toBe("https://www.okx.com/api/v5/account/balance");
    36→      expect(result.headers["OK-ACCESS-KEY"]).toBe("test-key");
    37→      expect(result.headers["OK-ACCESS-PASSPHRASE"]).toBe("test-pass");
    38→      expect(result.headers["OK-ACCESS-TIMESTAMP"]).toBe("2026-05-14T10:00:00.000Z");
    39→      // Signature should be a base64 string
    40→      expect(result.headers["OK-ACCESS-SIGN"]).toMatch(/^[A-Za-z0-9+/=]+$/);
    41→    });
    42→
    43→    it("produces known-value signature", () => {
    44→      const { createHmac } = require("node:crypto");
    45→      const credentials = { api_key: "test-key", secret: "test-secret", passphrase: "test-pass" };
    46→      const params = { method: "GET" as const, path: "/api/v5/account/balance", timestamp: "2026-05-14T10:00:00.000Z" };
    47→      const result = okxExchange.sign(credentials, params);
    48→
    49→      const expected = createHmac("sha256", "test-secret")
    50→        .update("2026-05-14T10:00:00.000ZGET/api/v5/account/balance")
    51→        .digest("base64");
    52→      expect(result.headers["OK-ACCESS-SIGN"]).toBe(expected);
    53→    });
    54→
    55→    it("includes body in prehash when provided", () => {
    56→      const credentials = { api_key: "k", secret: "s", passphrase: "p" };
    57→      const withBody = okxExchange.sign(credentials, {
    58→        method: "POST",
    59→        path: "/api/v5/trade/order",
    60→        timestamp: "2026-01-01T00:00:00Z",
    61→        body: '{"instId":"BTC-USDT"}',
    62→      });
    63→      const withoutBody = okxExchange.sign(credentials, {
    64→        method: "POST",
    65→        path: "/api/v5/trade/order",
    66→        timestamp: "2026-01-01T00:00:00Z",
    67→      });
    68→      // Different body should produce different signature
    69→      expect(withBody.headers["OK-ACCESS-SIGN"]).not.toBe(withoutBody.headers["OK-ACCESS-SIGN"]);
    70→    });
    71→
    72→    it("handles undefined passphrase gracefully", () => {
    73→      const credentials = { api_key: "key", secret: "secret" };
    74→      const params = { method: "GET" as const, path: "/api/v5/test", timestamp: "123" };
    75→      const result = okxExchange.sign(credentials, params);
    76→      expect(result.headers["OK-ACCESS-PASSPHRASE"]).toBe("");
    77→    });
    78→  });
    79→});
    80→

