     3→import { createHmac } from "node:crypto";
     4→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
     5→import type { TestResult } from "../types";
     6→
     7→const BASE_URL = "https://www.okx.com";
     8→
     9→export const okxExchange: Exchange = {
    10→  id: "okx",
    11→  name: "OKX",
    12→  fields: ["api_key", "secret", "passphrase"],
    13→  referral_url: "https://okx.com/join/80926498",
    14→  api_doc_url: "https://www.okx.com/account/my-api",
    15→
    16→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    17→    const { method, path, body } = params;
    18→    const timestamp = params.timestamp;
    19→    const prehash = timestamp + method + path + (body ?? "");
    20→    const signature = createHmac("sha256", credentials.secret)
    21→      .update(prehash)
    22→      .digest("base64");
    23→
    24→    return {
    25→      url: BASE_URL + path,
    26→      headers: {
    27→        "OK-ACCESS-KEY": credentials.api_key,
    28→        "OK-ACCESS-SIGN": signature,
    29→        "OK-ACCESS-TIMESTAMP": timestamp,
    30→        "OK-ACCESS-PASSPHRASE": credentials.passphrase ?? "",
    31→        "Content-Type": "application/json",
    32→      },
    33→    };
    34→  },
    35→
    36→  async testConnection(credentials: Credentials): Promise<TestResult> {
    37→    const timestamp = new Date().toISOString();
    38→    const path = "/api/v5/account/balance";
    39→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
    40→
    41→    const start = Date.now();
    42→    try {
    43→      const res = await fetch(signed.url, {
    44→        method: "GET",
    45→        headers: signed.headers,
    46→        signal: AbortSignal.timeout(10_000),
    47→      });
    48→      const latency_ms = Date.now() - start;
    49→      const json = (await res.json()) as { code?: string; msg?: string };
    50→
    51→      if (json.code === "0") {
    52→        return { success: true, latency_ms };
    53→      }
    54→      return { success: false, error: json.msg ?? `Error code: ${json.code}`, latency_ms };
    55→    } catch (e) {
    56→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
    57→    }
    58→  },
    59→};
