     1→import { createHmac } from "node:crypto";
     2→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
     3→import type { TestResult } from "../types";
     4→
     5→const BASE_URL = "https://api.binance.com";
     6→
     7→export const binanceExchange: Exchange = {
     8→  id: "binance",
     9→  name: "Binance",
    10→  fields: ["api_key", "secret"],
    11→  referral_url: "https://accounts.binance.com/register?ref=11427183",
    12→  api_doc_url: "https://www.binance.com/en/my/settings/api-management",
    13→  whitelist_ip: "195.135.193.235",
    14→
    15→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    16→    const { method, path } = params;
    17→    const queryString = params.params
    18→      ? Object.entries(params.params).map(([k, v]) => `${k}=${v}`).join("&")
    19→      : "";
    20→    const toSign = queryString + (queryString ? "&" : "") + `timestamp=${params.timestamp}`;
    21→    const signature = createHmac("sha256", credentials.secret)
    22→      .update(toSign)
    23→      .digest("hex");
    24→    const fullQuery = toSign + `&signature=${signature}`;
    25→
    26→    return {
    27→      url: `${BASE_URL}${path}?${fullQuery}`,
    28→      headers: {
    29→        "X-MBX-APIKEY": credentials.api_key,
    30→      },
    31→    };
    32→  },
    33→
    34→  async testConnection(credentials: Credentials): Promise<TestResult> {
    35→    const timestamp = Date.now().toString();
    36→    const path = "/api/v3/account";
    37→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
    38→
    39→    const start = Date.now();
    40→    try {
    41→      const res = await fetch(signed.url, {
    42→        method: "GET",
    43→        headers: signed.headers,
    44→        signal: AbortSignal.timeout(10_000),
    45→      });
    46→      const latency_ms = Date.now() - start;
    47→
    48→      if (res.ok) return { success: true, latency_ms };
    49→      const json = (await res.json()) as { msg?: string; code?: number };
    50→      return { success: false, error: json.msg ?? `HTTP ${res.status}`, latency_ms };
    51→    } catch (e) {
    52→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
    53→    }
    54→  },
    55→};
