    17→      expect(bybitExchange.api_doc_url).toBeDefined();
    18→    });
    19→  });
    20→
    21→  describe("sign", () => {
    22→    it("produces hex HMAC-SHA256 signature with correct URL and headers", () => {
    23→      const credentials = { api_key: "test-key", secret: "test-secret" };
    24→      const params = {
    25→        method: "GET" as const,
    26→        path: "/v5/account/wallet-balance",
    27→        timestamp: "1700000000000",
    28→        params: { accountType: "UNIFIED" },
    29→      };
    30→
    31→      const result = bybitExchange.sign(credentials, params);
    32→
    33→      expect(result.url).toBe("https://api.bybit.com/v5/account/wallet-balance?accountType=UNIFIED");
    34→      expect(result.headers["X-BAPI-API-KEY"]).toBe("test-key");
    35→      expect(result.headers["X-BAPI-TIMESTAMP"]).toBe("1700000000000");
    36→      expect(result.headers["X-BAPI-RECV-WINDOW"]).toBe("5000");
