    11→  referral_url: "https://www.gate.io/signup",
    12→  api_doc_url: "https://www.gate.io/myaccount/api_key_manage",
    13→
    14→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    15→    const { method, path, body } = params;
    16→    const timestamp = params.timestamp;
    17→    const queryString = params.params
    18→      ? Object.entries(params.params).map(([k, v]) => `${k}=${v}`).join("&")
    19→      : "";
    20→    const hashedBody = createHash("sha512").update(body ?? "").digest("hex");
    21→    const prehash = `${method}\n${path}\n${queryString}\n${hashedBody}\n${timestamp}`;
    22→    const signature = createHmac("sha512", credentials.secret)
    23→      .update(prehash)
    24→      .digest("hex");
    25→
    26→    const url = queryString
    27→      ? `${BASE_URL}${path}?${queryString}`
    28→      : `${BASE_URL}${path}`;
    29→
    30→    return {
    31→      url,
    32→      headers: {
    33→        KEY: credentials.api_key,
    34→        SIGN: signature,
    35→        Timestamp: timestamp,
    36→        "Content-Type": "application/json",
    37→      },
    38→    };
    39→  },
    40→
    41→  async testConnection(credentials: Credentials): Promise<TestResult> {
    42→    const timestamp = Math.floor(Date.now() / 1000).toString();
    43→    const path = "/api/v4/spot/accounts";
    44→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
    45→
    46→    const start = Date.now();
    47→    try {
    48→      const res = await fetch(signed.url, { method: "GET", headers: signed.headers, signal: AbortSignal.timeout(10_000) });
    49→      const latency_ms = Date.now() - start;
    50→      if (res.ok) return { success: true, latency_ms };
    51→      const json = (await res.json()) as { message?: string };
    52→      return { success: false, error: json.message ?? `HTTP ${res.status}`, latency_ms };
    53→    } catch (e) {
    54→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
    55→    }
    56→  },
    57→};
