     1→import { createHmac } from "node:crypto";
     2→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
     3→import type { TestResult } from "../types";
     4→
     5→const BASE_URL = "https://api.kucoin.com";
     6→
     7→export const kucoinExchange: Exchange = {
     8→  id: "kucoin",
     9→  name: "KuCoin",
    10→  fields: ["api_key", "secret", "passphrase"],
    11→  referral_url: "https://www.kucoin.com/r/af/REFERRAL",
    12→  api_doc_url: "https://www.kucoin.com/account/api",
    13→
    14→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    15→    const { method, path, body } = params;
    16→    const timestamp = params.timestamp;
    17→    const prehash = timestamp + method + path + (body ?? "");
    18→    const signature = createHmac("sha256", credentials.secret)
    19→      .update(prehash)
    20→      .digest("base64");
    21→    const passphraseSign = createHmac("sha256", credentials.secret)
    22→      .update(credentials.passphrase ?? "")
    23→      .digest("base64");
    24→
    25→    return {
    26→      url: BASE_URL + path,
    27→      headers: {
    28→        "KC-API-KEY": credentials.api_key,
    29→        "KC-API-SIGN": signature,
    30→        "KC-API-TIMESTAMP": timestamp,
    31→        "KC-API-PASSPHRASE": passphraseSign,
    32→        "KC-API-KEY-VERSION": "2",
    33→        "Content-Type": "application/json",
    34→      },
    35→    };
    36→  },
    37→
    38→  async testConnection(credentials: Credentials): Promise<TestResult> {
    39→    const timestamp = Date.now().toString();
    40→    const path = "/api/v1/accounts";
    41→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
    42→
    43→    const start = Date.now();
    44→    try {
    45→      const res = await fetch(signed.url, { method: "GET", headers: signed.headers, signal: AbortSignal.timeout(10_000) });
    46→      const latency_ms = Date.now() - start;
    47→      const json = (await res.json()) as { code?: string; msg?: string };
    48→      if (json.code === "200000") return { success: true, latency_ms };
    49→      return { success: false, error: json.msg ?? `Error: ${json.code}`, latency_ms };
    50→    } catch (e) {
    51→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
    52→    }
    53→  },
    54→};
